// Writes src/abi.generated.ts from the forge build output (run `forge build` first).
import { readFileSync, writeFileSync } from "node:fs";

const out = new URL("../../out/", import.meta.url);
const abiOf = (name: string) => JSON.parse(readFileSync(new URL(`${name}.sol/${name}.json`, out), "utf8")).abi;

const text =
  "// Generated by scripts/gen-abi.ts from the forge build output. Do not edit.\n\n" +
  `export const routerAbi = ${JSON.stringify(abiOf("FillmarkRouterV3"), null, 2)} as const;\n\n` +
  `export const feedsAbi = ${JSON.stringify(abiOf("FillmarkFeeds"), null, 2)} as const;\n`;
writeFileSync(new URL("../src/abi.generated.ts", import.meta.url), text);
